const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-122.555169, 40.190004]);
  const date = '2020-08-25';

  // 2. Data Acquisition - MERRA-2 Aerosol Diagnostics
  const collection = ee.ImageCollection('M2T1NXAER')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(point);

  const collectionSize = collection.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the first image (should be only one per day for MERRA-2)
  const image = collection.first();

  // 3. Processing - Extract black carbon column density
  const bcColumn = image.select('BCCOLUMN'); // Total column black carbon in kg/m^2

  // 4. Calculate value at point
  const result = bcColumn.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 50000, // MERRA-2 resolution is ~50km
    maxPixels: 1e9
  });

  const bcValue = result.get('BCCOLUMN').getInfo();
  console.log(`Black Carbon Column (kg/m^2): ${bcValue}`);

  // Check for valid data
  if (bcValue === null || bcValue === undefined) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (isNaN(bcValue) || !isFinite(bcValue)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert from kg/m^2 to mg/m^2 and check threshold
  const bc_mg_per_m2 = bcValue * 1000000; // kg/m^2 to mg/m^2
  console.log(`Black Carbon (mg/m^2): ${bc_mg_per_m2.toFixed(2)}`);

  // 5. Validation & Final Answer
  if (bc_mg_per_m2 > 12) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
